"""Application KyberAI.   python app.py   puis ouvrir http://127.0.0.1:7860"""
import base64
import hashlib
import os
import html
import time
import gradio as gr
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
from kyber import Kyber
from leakage import IMPLEMENTATIONS, collect, analyze

RED, NAVY, GREY = "#D0271D", "#121C4E", "#5F6170"
STATE = {}
LOGO = ""   # icône du logo KYBER de la présentation   # logo KYBER de la présentation (intégré, aucun fichier à copier)
IMPL_NAMES = list(IMPLEMENTATIONS)          # [naïve, temps constant]
CHOICES = ["Version naïve", "Version temps constant"]


def hexs(b, n=16):
    return " ".join(f"{x:02X}" for x in b[:n]) + " …"


def xor_stream(key, data):
    """Chiffrement symétrique simple avec la clé partagée (flux SHAKE-256)."""
    stream = hashlib.shake_256(key).digest(len(data))
    return bytes(a ^ b for a, b in zip(data, stream))


def card(title, body, tone=""):
    return f'<div class="kc {tone}"><div class="kt">{title}</div>{body}</div>'


EMPTY = card("En attente", '<p class="muted">Cliquez sur le bouton pour commencer.</p>')


# ---------------------------------------------------------------- onglet 1
def step_keys(level):
    kb = Kyber(level)
    t = time.perf_counter(); ek, dk = kb.keygen(); dt = (time.perf_counter() - t) * 1000
    STATE.update(kb=kb, ek=ek, dk=dk)
    body = (f'<div class="row"><span class="lbl">Clé publique</span><code>{hexs(ek)}</code><span class="sz">{len(ek)} octets</span></div>'
            f'<div class="row"><span class="lbl">Clé secrète</span><code>•••• •••• •••• ••••</code><span class="sz">{len(dk)} octets</span></div>'
            f'<p class="muted">{level} · générées en {dt:.1f} ms</p>')
    return card("① Bob a ses clés", body, "ok")


def step_send(message):
    if "ek" not in STATE:
        return card("Bob", '<p class="muted">Générez d’abord les clés de Bob (bouton ①).</p>', "warn")
    kb, ek, dk = STATE["kb"], STATE["ek"], STATE["dk"]
    K_a, c = kb.encaps(ek)
    data = xor_stream(K_a, message.encode("utf-8"))
    K_b = kb.decaps(dk, c)
    plain = xor_stream(K_b, data).decode("utf-8", errors="replace")
    alice = card("② Alice envoie",
                 f'<div class="row"><span class="lbl">Message</span><b>{html.escape(message)}</b></div>'
                 f'<div class="row"><span class="lbl">Secret</span><code>{K_a.hex()[:16].upper()} …</code></div>')
    pirate = card("Ce que voit un pirate",
                  f'<div class="row"><span class="lbl">Chiffré Kyber</span><code>{hexs(c, 12)}</code></div>'
                  f'<div class="row"><span class="lbl">Message chiffré</span><code>{hexs(data, 12)}</code></div>'
                  '<p class="muted">Illisible sans la clé secrète de Bob.</p>', "dark")
    same = K_a == K_b
    bob = card("③ Bob reçoit",
               f'<div class="row"><span class="lbl">Secret</span><code>{K_b.hex()[:16].upper()} …</code>'
               f'<span class="pill {"g" if same else "r"}">{"identique" if same else "différent"}</span></div>'
               f'<div class="big">{html.escape(plain)}</div>', "ok" if same else "warn")
    return f'<div class="grid3">{alice}{pirate}{bob}</div>'


# ---------------------------------------------------------------- onglet 2
def run_detector(choice, n_traces, jitter, progress=gr.Progress()):
    compare = IMPLEMENTATIONS[IMPL_NAMES[CHOICES.index(choice)]]
    traces, labels = collect(compare, n_traces=int(n_traces), jitter_us=float(jitter),
                             progress=lambda f: progress(f, desc="Mesure des temps…"))
    progress(1.0, desc="L’IA apprend…")
    r = analyze(traces, labels)
    fig, ax = plt.subplots(figsize=(6.4, 3.2), dpi=130)
    tmin = traces.min(1)
    ax.hist(tmin[labels == 0], bins=40, alpha=.8, color=NAVY, label="message inchangé")
    ax.hist(tmin[labels == 1], bins=40, alpha=.75, color=RED, label="message changé")
    ax.set_xlabel("temps de vérification (µs)", color=GREY); ax.set_ylabel("mesures", color=GREY)
    ax.tick_params(colors=GREY); ax.spines[["top", "right"]].set_visible(False)
    for s in ("left", "bottom"): ax.spines[s].set_color("#C9CCD6")
    ax.legend(frameon=False); fig.tight_layout()
    acc = 100 * r["accuracy"]
    if r["leak"]:
        head, tone, txt = "Fuite détectée", "bad", "L’IA devine le secret rien qu’avec le temps. Le code doit être corrigé."
    else:
        head, tone, txt = "Aucune fuite", "good", "L’IA ne fait pas mieux que le hasard. Le temps ne révèle rien."
    verdict = (f'<div class="verdict {tone}"><div class="vh">{head}</div><p>{txt}</p>'
               f'<div class="meter"><span style="width:{acc:.0f}%"></span><i style="left:{100*r["chance"]:.0f}%"></i></div>'
               f'<div class="stats"><div><b>{acc:.0f} %</b><span>précision de l’IA</span></div>'
               f'<div><b>{100*r["chance"]:.0f} %</b><span>hasard</span></div>'
               f'<div><b>{abs(r["t_stat"]):.1f}</b><span>test t (seuil 4,5)</span></div></div></div>')
    return verdict, fig


